import unittest
from unittest.mock import MagicMock, patch, PropertyMock
import werkzeug.test
from werkzeug.test import EnvironBuilder
from werkzeug.wrappers import BaseRequest

from flask import Flask, json
from flask.testing import FlaskClient
from flask.ctx import AppContext


class TestFlaskClientOpen(unittest.TestCase):
    def setUp(self):
        self.app = Flask(__name__)
        self.app.config["TESTING"] = True
        self.client = FlaskClient(self.app)

    def test_open_with_args_string_path(self):
        """Test open with standard path string arguments."""
        @self.app.route("/")
        def index():
            return "Hello"

        @self.app.route("/data")
        def data():
            return self.app.json_response({"key": "value"})

        # Test simple GET
        rv = self.client.open("/")
        self.assertEqual(rv.status_code, 200)
        self.assertEqual(rv.data, b"Hello")

        # Test JSON response handling
        rv = self.client.open("/data")
        self.assertEqual(rv.json, {"key": "value"})
        self.assertEqual(rv.json_module, json)

    def test_open_with_environ_builder(self):
        """Test open passing an EnvironBuilder object."""
        @self.app.route("/builder")
        def builder_route():
            return "Builder"

        builder = EnvironBuilder(path="/builder", method="GET")
        # Pass builder as first arg
        rv = self.client.open(builder)
        self.assertEqual(rv.status_code, 200)

    def test_open_with_environ_builder_with_base_environ(self):
        """Test open with EnvironBuilder ensuring environ_base is handled."""
        @self.app.route("/")
        def index():
            return "ok"

        # Create a builder with a custom environ_base
        builder = EnvironBuilder(path="/", method="GET")
        builder.environ_base = {"HTTP_X_CUSTOM": "value"}

        rv = self.client.open(builder)
        self.assertEqual(rv.status_code, 200)

    def test_open_with_dict_environ(self):
        """Test open passing a dictionary representing an environ."""
        @self.app.route("/env")
        def env_route():
            return "Env"

        # Create a valid environ dict manually
        builder = EnvironBuilder(path="/env", method="GET")
        environ_dict = builder.get_environ()

        rv = self.client.open(environ_dict)
        self.assertEqual(rv.status_code, 200)

    def test_open_with_base_request(self):
        """Test open passing a BaseRequest object."""
        @self.app.route("/request")
        def req_route():
            return "Request"

        builder = EnvironBuilder(path="/request", method="GET")
        request = builder.get_request()

        rv = self.client.open(request)
        self.assertEqual(rv.status_code, 200)

    def test_open_follow_redirects(self):
        """Test open with follow_redirects enabled."""
        @self.app.route("/redirect")
        def redirect_route():
            return self.app.redirect("/target")

        @self.app.route("/target")
        def target_route():
            return "Target"

        rv = self.client.open("/redirect", follow_redirects=True)
        self.assertEqual(rv.status_code, 200)
        self.assertEqual(rv.data, b"Target")

    def test_open_buffered(self):
        """Test open with buffered parameter."""
        @self.app.route("/")
        def index():
            return "Buffered"

        rv = self.client.open("/", buffered=True)
        self.assertEqual(rv.status_code, 200)
        self.assertIsNotNone(rv.data)

    def test_open_context_stack_management(self):
        """Test that previous contexts are popped and new ones are pushed."""
        @self.app.route("/")
        def index():
            return "Context"

        # Mock the internal list to simulate context creation during request
        mock_context = MagicMock(spec=AppContext)
        mock_cm = MagicMock()
        mock_cm.__enter__ = MagicMock(return_value=mock_context)
        mock_cm.__exit__ = MagicMock(return_value=False)

        self.client._new_contexts.append(mock_cm)

        rv = self.client.open("/")

        # Assert stack interactions
        self.assertEqual(rv.status_code, 200)
        # The list should be cleared after processing
        self.assertEqual(len(self.client._new_contexts), 0)
        # The context manager from the list should have been entered
        mock_cm.__enter__.assert_called_once()

    def test_open_kwargs_passed_to_builder(self):
        """Test that kwargs are correctly passed to _request_from_builder_args."""
        @self.app.route("/post", methods=["POST"])
        def post_route():
            return self.app.json_response({"received": True})

        rv = self.client.open("/post", method="POST", json={"test": "data"})
        self.assertEqual(rv.status_code, 200)
        self.assertEqual(rv.json["received"], True)

    def test_open_mixed_args_kwargs(self):
        """Test calling with path in args and other options in kwargs."""
        @self.app.route("/mixed")
        def mixed_route():
            return "Mixed"

        # path in args, method in kwargs
        rv = self.client.open("/mixed", method="GET")
        self.assertEqual(rv.status_code, 200)

    def test_open_preserve_context_attribute_exists(self):
        """Verify class initialization of preserve_context used in request logic."""
        client = FlaskClient(self.app)
        self.assertFalse(client.preserve_context)

    def test_open_context_stack_initialization(self):
        """Verify context stack is initialized."""
        client = FlaskClient(self.app)
        self.assertIsNotNone(client._context_stack)

    def test_open_application_json_module_assignment(self):
        """Test that the app's json module is attached to the response."""
        @self.app.route("/json_route")
        def json_route():
            return self.app.json_response({"foo": "bar"})

        rv = self.client.open("/json_route")
        self.assertEqual(rv.json_module, self.app.json)

if __name__ == "__main__":
    unittest.main()

