import pytest
import typing as t
from unittest.mock import Mock, patch, MagicMock
from flask import Flask, current_app
from flask.views import View
from werkzeug.exceptions import MethodNotAllowed

# Import the actual function from the module
import sys
import os
sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), '../../..')))

from flask.views import view as view_function

class TestViewFunction:
    """Test cases for the view function in flask/views.py"""

    @pytest.fixture
    def mock_view_class(self):
        """Create a mock view class for testing"""
        class MockView(View):
            def dispatch_request(self, **kwargs):
                return {"message": "dispatched", "kwargs": kwargs}

        return MockView

    @pytest.fixture
    def mock_app(self):
        """Create a mock Flask application"""
        app = Flask(__name__)
        return app

    @pytest.fixture
    def view_instance(self, mock_view_class):
        """Create a view instance with test parameters"""
        return mock_view_class()

    def test_view_basic_functionality(self, mock_view_class, mock_app):
        """Test basic view function execution"""
        # Setup
        class_args = ()
        class_kwargs = {}
        view_kwargs = {"id": 123, "name": "test"}

        # Mock the view attribute on the function
        view_function.view_class = mock_view_class

        # Execute
        with mock_app.app_context():
            result = view_function(**view_kwargs)

        # Assert
        assert result == {"message": "dispatched", "kwargs": view_kwargs}

    def test_view_with_class_args(self, mock_view_class, mock_app):
        """Test view function with class arguments"""
        # Setup
        class_args = ("arg1", "arg2")
        class_kwargs = {"init_param": "value"}
        view_kwargs = {"id": 456}

        # Create a custom mock view class that accepts init parameters
        class CustomView(View):
            def __init__(self, *args, **kwargs):
                self.init_args = args
                self.init_kwargs = kwargs
                super().__init__()

            def dispatch_request(self, **kwargs):
                return {
                    "init_args": self.init_args,
                    "init_kwargs": self.init_kwargs,
                    "dispatch_kwargs": kwargs
                }

        view_function.view_class = CustomView
        view_function.__globals__['class_args'] = class_args
        view_function.__globals__['class_kwargs'] = class_kwargs

        # Execute
        with mock_app.app_context():
            result = view_function(**view_kwargs)

        # Assert
        assert result["init_args"] == class_args
        assert result["init_kwargs"] == class_kwargs
        assert result["dispatch_kwargs"] == view_kwargs

    def test_view_with_different_response_types(self, mock_app):
        """Test view function with different response return types"""
        # Setup - Test with string response
        class StringView(View):
            def dispatch_request(self, **kwargs):
                return f"Response with id: {kwargs.get('id', 'none')}"

        view_function.view_class = StringView
        view_kwargs = {"id": "test_id"}

        # Execute
        with mock_app.app_context():
            result = view_function(**view_kwargs)

        # Assert
        assert result == "Response with id: test_id"

        # Setup - Test with tuple response
        class TupleView(View):
            def dispatch_request(self, **kwargs):
                return ({"data": "test"}, 201, {"X-Custom": "Header"})

        view_function.view_class = TupleView

        # Execute
        with mock_app.app_context():
            result = view_function(**view_kwargs)

        # Assert
        assert result == ({"data": "test"}, 201, {"X-Custom": "Header"})

    def test_view_with_exception_in_dispatch(self, mock_app):
        """Test view function when dispatch_request raises an exception"""
        # Setup
        class ErrorView(View):
            def dispatch_request(self, **kwargs):
                raise ValueError("Test error")

        view_function.view_class = ErrorView
        view_kwargs = {"param": "test"}

        # Execute and assert
        with mock_app.app_context():
            with pytest.raises(ValueError, match="Test error"):
                view_function(**view_kwargs)

    def test_view_with_method_not_allowed(self, mock_app):
        """Test view function with MethodNotAllowed exception"""
        # Setup
        class MethodRestrictedView(View):
            methods = ['GET', 'POST']

            def dispatch_request(self, **kwargs):
                if kwargs.get('method') not in self.methods:
                    raise MethodNotAllowed(valid_methods=self.methods)
                return {"method": kwargs.get('method')}

        view_function.view_class = MethodRestrictedView

        # Test with allowed method
        with mock_app.app_context():
            result = view_function(method="GET")
            assert result == {"method": "GET"}

        # Test with disallowed method
        with mock_app.app_context():
            with pytest.raises(MethodNotAllowed):
                view_function(method="PUT")

    def test_view_with_async_dispatch(self, mock_app):
        """Test view function with async dispatch_request method"""
        # Setup
        import asyncio

        class AsyncView(View):
            async def dispatch_request(self, **kwargs):
                await asyncio.sleep(0.01)
                return {"async": True, "kwargs": kwargs}

        view_function.view_class = AsyncView
        view_kwargs = {"async_param": "test"}

        # Execute
        with mock_app.app_context():
            result = view_function(**view_kwargs)

        # Assert
        assert result == {"async": True, "kwargs": view_kwargs}

    def test_view_with_decorators(self, mock_app):
        """Test view function with decorators applied"""
        # Setup
        decorator_called = []

        def test_decorator(func):
            def wrapper(*args, **kwargs):
                decorator_called.append("before")
                result = func(*args, **kwargs)
                decorator_called.append("after")
                return result
            return wrapper

        class DecoratedView(View):
            decorators = [test_decorator]

            def dispatch_request(self, **kwargs):
                return {"decorated": True, "kwargs": kwargs}

        view_function.view_class = DecoratedView
        view_kwargs = {"test": "decorator"}

        # Execute
        with mock_app.app_context():
            result = view_function(**view_kwargs)

        # Assert
        assert result == {"decorated": True, "kwargs": view_kwargs}
        assert decorator_called == ["before", "after"]

    def test_view_with_provide_automatic_options(self, mock_app):
        """Test view function with provide_automatic_options setting"""
        # Setup
        class OptionsView(View):
            provide_automatic_options = False

            def dispatch_request(self, **kwargs):
                return {"options_disabled": True, "kwargs": kwargs}

        view_function.view_class = OptionsView
        view_kwargs = {"option_test": "value"}

        # Execute
        with mock_app.app_context():
            result = view_function(**view_kwargs)

        # Assert
        assert result == {"options_disabled": True, "kwargs": view_kwargs}

    def test_view_with_init_every_request_false(self, mock_app):
        """Test view function with init_every_request=False"""
        # Setup
        instance_count = 0

        class SingleInstanceView(View):
            init_every_request = False

            def __init__(self):
                nonlocal instance_count
                instance_count += 1
                self.instance_id = instance_count
                super().__init__()

            def dispatch_request(self, **kwargs):
                return {"instance_id": self.instance_id, "kwargs": kwargs}

        view_function.view_class = SingleInstanceView

        # Execute multiple times
        with mock_app.app_context():
            result1 = view_function(call="first")
            result2 = view_function(call="second")

        # Assert - same instance should be used
        assert result1["instance_id"] == 1
        assert result2["instance_id"] == 1  # Same instance reused

    def test_view_with_empty_kwargs(self, mock_view_class, mock_app):
        """Test view function with no keyword arguments"""
        # Setup
        view_function.view_class = mock_view_class

        # Execute
        with mock_app.app_context():
            result = view_function()

        # Assert
        assert result == {"message": "dispatched", "kwargs": {}}

    def test_view_with_nested_kwargs(self, mock_view_class, mock_app):
        """Test view function with nested dictionary in kwargs"""
        # Setup
        view_function.view_class = mock_view_class
        nested_kwargs = {
            "user": {
                "id": 123,
                "name": "John",
                "preferences": {"theme": "dark", "language": "en"}
            },
            "metadata": {"timestamp": "2024-01-01", "source": "api"}
        }

        # Execute
        with mock_app.app_context():
            result = view_function(**nested_kwargs)

        # Assert
        assert result == {"message": "dispatched", "kwargs": nested_kwargs}

    @patch('flask.views.current_app')
    def test_view_with_mocked_current_app(self, mock_current_app, mock_view_class):
        """Test view function with mocked current_app"""
        # Setup
        mock_response = {"mocked": "response"}
        mock_dispatch = Mock(return_value=mock_response)
        mock_view_instance = Mock()
        mock_view_instance.dispatch_request = mock_dispatch
        mock_view_class_instance = Mock(return_value=mock_view_instance)

        mock_ensure_sync = Mock(return_value=mock_dispatch)
        mock_current_app.ensure_sync = mock_ensure_sync

        view_function.view_class = mock_view_class_instance
        view_kwargs = {"test": "mock"}

        # Execute
        result = view_function(**view_kwargs)

        # Assert
        mock_view_class_instance.assert_called_once()
        mock_ensure_sync.assert_called_once_with(mock_dispatch)
        mock_dispatch.assert_called_once_with(**view_kwargs)
        assert result == mock_response

