import unittest
from unittest.mock import Mock, patch
import flask.typing as ft
from flask import App


class TestAddTemplateFilter(unittest.TestCase):
    def setUp(self):
        self.app = App(__name__)
        self.app.jinja_env = Mock()
        self.app.jinja_env.filters = {}

    def test_add_template_filter_with_name(self):
        """Test adding template filter with custom name"""
        def custom_filter(value):
            return value.upper()

        self.app.add_template_filter(custom_filter, name='my_filter')

        self.assertIn('my_filter', self.app.jinja_env.filters)
        self.assertEqual(self.app.jinja_env.filters['my_filter'], custom_filter)
        self.assertEqual(self.app.jinja_env.filters['my_filter']('test'), 'TEST')

    def test_add_template_filter_without_name(self):
        """Test adding template filter using function name"""
        def custom_filter(value):
            return value.lower()

        self.app.add_template_filter(custom_filter)

        self.assertIn('custom_filter', self.app.jinja_env.filters)
        self.assertEqual(self.app.jinja_env.filters['custom_filter'], custom_filter)
        self.assertEqual(self.app.jinja_env.filters['custom_filter']('TEST'), 'test')

    def test_add_template_filter_overwrites_existing(self):
        """Test that adding filter with same name overwrites previous"""
        def first_filter(value):
            return value * 2

        def second_filter(value):
            return value + value

        self.app.jinja_env.filters['duplicate'] = first_filter
        self.app.add_template_filter(second_filter, name='duplicate')

        self.assertIn('duplicate', self.app.jinja_env.filters)
        self.assertEqual(self.app.jinja_env.filters['duplicate'], second_filter)
        self.assertEqual(self.app.jinja_env.filters['duplicate']('ab'), 'abab')

    def test_add_template_filter_with_lambda(self):
        """Test adding lambda function as template filter"""
        lambda_filter = lambda x: x[::-1]

        self.app.add_template_filter(lambda_filter, name='reverse')

        self.assertIn('reverse', self.app.jinja_env.filters)
        self.assertEqual(self.app.jinja_env.filters['reverse']('hello'), 'olleh')

