from flask import Flask, json
from flask.json import dumps, JSONEncoder

@pytest.fixture
def app():
    app = Flask(__name__)
    return app

def test_dumps_standard_json():
    obj = {"key": "value"}
    result = dumps(obj)
    assert result == '{"key": "value"}'

def test_dumps_with_kwargs():
    obj = {"key": "value"}
    result = dumps(obj, indent=2)
    assert result == '{\n  "key": "value"\n}'

def test_dumps_with_flask_context(app):
    with app.app_context():
        obj = {"key": "value"}
        result = dumps(obj)
        assert result == '{"key": "value"}'

def test_dumps_non_serializable_object():
    class NonSerializable:
        pass

    obj = NonSerializable()
    with pytest.raises(TypeError):
        dumps(obj)

def test_dumps_custom_serializer(app):
    class CustomObject:
        pass

    class CustomJSONEncoder(JSONEncoder):
        def default(self, obj):
            if isinstance(obj, CustomObject):
                return {"custom": "object"}
            return super().default(obj)

    app.json_encoder = CustomJSONEncoder

    with app.app_context():
        obj = CustomObject()
        result = dumps(obj)
        assert result == '{"custom": "object"}'

