import pytest
from flask import Flask, json
from flask.testing import FlaskClient, TestResponse
from werkzeug.test import EnvironBuilder
from werkzeug.exceptions import HTTPException

class TestFlaskClientOpen:
    @pytest.fixture
    def app(self):
        app = Flask(__name__)

        @app.route('/hello')
        def hello():
            return 'Hello, World!'

        return app

    @pytest.fixture
    def client(self, app):
        return app.test_client()

    def test_open_with_valid_path(self, client):
        response = client.open('/hello')
        assert response.status_code == 200
        assert response.data == b'Hello, World!'

    def test_open_with_buffered(self, client):
        response = client.open('/hello', buffered=True)
        assert response.status_code == 200
        assert response.data == b'Hello, World!'

    def test_open_with_follow_redirects(self, client):
        @client.application.route('/redirect')
        def redirect():
            return '', 302, {'Location': '/hello'}

        response = client.open('/redirect', follow_redirects=True)
        assert response.status_code == 200
        assert response.data == b'Hello, World!'

    def test_open_with_invalid_path(self, client):
        response = client.open('/invalid')
        assert response.status_code == 404

    def test_open_with_environ_builder(self, client):
        builder = EnvironBuilder(path='/hello')
        response = client.open(builder)
        assert response.status_code == 200
        assert response.data == b'Hello, World!'

    def test_open_with_invalid_args(self, client):
        with pytest.raises(ValueError):
            client.open(123)

    def test_open_with_json_response(self, client):
        @client.application.route('/json')
        def json_route():
            return json.jsonify(message='Hello, JSON!')

        response = client.open('/json')
        assert response.status_code == 200
        assert response.json == {'message': 'Hello, JSON!'}

    def test_open_with_exception(self, client):
        @client.application.route('/error')
        def error():
            raise HTTPException('This is an error')

        response = client.open('/error')
        assert response.status_code == 500

