import pytest
from unittest.mock import Mock, patch
import click

# Assuming the decorator function is defined in the same module for testing purposes
def decorator(ctx: click.Context, /, *args: t.Any, **kwargs: t.Any) -> t.Any:
    # Mock implementation of the decorator function
    if not hasattr(ctx, 'invoke'):
        raise RuntimeError("Invalid context")
    if not hasattr(ctx, 'current_app'):
        ctx.current_app = Mock()
    if not ctx.current_app._get_current_object():
        ctx.current_app._get_current_object = Mock(return_value=True)
    return ctx.invoke(args[0], *args[1:], **kwargs)

# Mocking a function to be used with the decorator
def mock_function(*args, **kwargs):
    return "Function executed"

@pytest.fixture
def mock_ctx():
    ctx = Mock(spec=click.Context)
    ctx.invoke = Mock(return_value="Function executed")
    return ctx

@pytest.fixture
def mock_current_app():
    with patch('flask.cli.current_app', new_callable=Mock) as mock_app:
        yield mock_app

@pytest.fixture
def mock_load_app():
    with patch('flask.cli.load_app', new_callable=Mock) as mock_load:
        yield mock_load

def test_decorator_with_active_context(mock_ctx, mock_current_app):
    # Simulate an active application context
    mock_current_app._get_current_object.return_value = True

    result = decorator(mock_ctx, mock_function, 1, 2, key='value')
    assert result == "Function executed"
    mock_current_app._get_current_object.assert_called_once()
    mock_ctx.invoke.assert_called_once_with(mock_function, 1, 2, key='value')

def test_decorator_without_active_context(mock_ctx, mock_current_app, mock_load_app):
    # Simulate no active application context
    mock_current_app._get_current_object.return_value = None

    result = decorator(mock_ctx, mock_function, 1, 2, key='value')
    assert result == "Function executed"
    mock_load_app.assert_called_once()
    mock_ctx.invoke.assert_called_once_with(mock_function, 1, 2, key='value')

def test_decorator_with_exception(mock_ctx, mock_current_app):
    # Simulate an active application context
    mock_current_app._get_current_object.return_value = True

    # Mock the function to raise an exception
    def mock_function_with_exception(*args, **kwargs):
        raise Exception("Test exception")

    with pytest.raises(Exception, match="Test exception"):
        decorator(mock_ctx, mock_function_with_exception, 1, 2, key='value')
    mock_current_app._get_current_object.assert_called_once()
    mock_ctx.invoke.assert_called_once_with(mock_function_with_exception, 1, 2, key='value')

