from flask import Flask
import flask.views as flask_views

# Import the function under test
from flask.views import view as view_func


def test_view_calls_dispatch_with_kwargs(monkeypatch):
    storage = {'kwargs': None}

    class DummyView:
        def dispatch_request(self, **kwargs):
            storage['kwargs'] = kwargs
            return {"status": "ok", "received": kwargs}

    # Patch the view_class used by the view function
    monkeypatch.setattr(flask_views, 'view_class', DummyView)

    app = Flask(__name__)
    with app.app_context():
        result = view_func(param1='value1', param2=2)

    assert storage['kwargs'] == {'param1': 'value1', 'param2': 2}
    assert result == {"status": "ok", "received": {'param1': 'value1', 'param2': 2}}


def test_view_raises_attribute_error_when_view_class_missing(monkeypatch):
    # Ensure view_class attribute is removed if present
    monkeypatch.delattr(flask_views, 'view_class', raising=False)

    app = Flask(__name__)
    with app.app_context():
        with pytest.raises(AttributeError):
            view_func()


def test_view_raises_type_error_on_incompatible_kwargs(monkeypatch):
    class BadView:
        def dispatch_request(self, a):
            return a

    monkeypatch.setattr(flask_views, 'view_class', BadView)

    app = Flask(__name__)
    with app.app_context():
        with pytest.raises(TypeError):
            view_func(a=1, b=2)


def test_view_calls_dispatch_request_with_no_kwargs(monkeypatch):
    storage = {'kwargs': None}

    class EmptyView:
        def dispatch_request(self, **kwargs):
            storage['kwargs'] = kwargs
            return "empty"

    monkeypatch.setattr(flask_views, 'view_class', EmptyView)

    app = Flask(__name__)
    with app.app_context():
        result = view_func()

    assert storage['kwargs'] == {}
    assert result == "empty"

