import unittest
from flask import Flask
from flask.json import loads, JSONProvider
from unittest.mock import patch

class FakeJSONProvider(JSONProvider):
    def __init__(self, app):
        super().__init__(app)
        self.called_with = None

    def loads(self, s, **kwargs):
        self.called_with = s
        return {"provider": "FakeJSONProvider", "payload": s}


class TestLoads(unittest.TestCase):

    def test_loads_uses_app_json_in_context(self):
        app = Flask(__name__)
        app.json_provider_class = FakeJSONProvider

        with app.app_context():
            result = loads('{"a": 1}')
            self.assertEqual(result, {"provider": "FakeJSONProvider", "payload": '{"a": 1}'})
            provider = app.json
            self.assertIsNotNone(provider)
            self.assertEqual(provider.called_with, '{"a": 1}')

    def test_loads_uses_standard_json_when_no_context(self):
        with patch('json.loads') as mock_json_loads:
            mock_json_loads.return_value = {"ok": True}
            result = loads('{"ok": true}')
            mock_json_loads.assert_called_once_with('{"ok": true}')
            self.assertEqual(result, {"ok": True})

    def test_loads_raises_value_error_when_invalid_json_no_context(self):
        with patch('json.loads', side_effect=ValueError) as mock_json_loads:
            with self.assertRaises(ValueError):
                loads('not json')
            mock_json_loads.assert_called_once_with('not json')

    def test_loads_with_bytes_no_context(self):
        with patch('json.loads') as mock_json_loads:
            mock_json_loads.return_value = {"bytes": True}
            result = loads(b'{"byte": true}')
            mock_json_loads.assert_called_once_with(b'{"byte": true}')
            self.assertEqual(result, {"bytes": True})


if __name__ == '__main__':
    unittest.main()

