class TestAddTemplateFilter:
    """Test suite for the App.add_template_filter method."""

    def test_add_template_filter_with_name(self, app: ConcreteAppForTesting):
        """Test registering a filter with a specific name."""
        def custom_filter(s: str) -> str:
            return s.upper()

        app.add_template_filter(custom_filter, name="my_upper")

        assert "my_upper" in app.jinja_env.filters
        assert app.jinja_env.filters["my_upper"] == custom_filter

    def test_add_template_filter_without_name(self, app: ConcreteAppForTesting):
        """Test registering a filter without a name (uses function name)."""
        def reverse(s: str) -> str:
            return s[::-1]

        app.add_template_filter(reverse)

        assert "reverse" in app.jinja_env.filters
        assert app.jinja_env.filters["reverse"] == reverse

    def test_add_template_filter_overwrites_existing(self, app: ConcreteAppForTesting):
        """Test that registering a filter overwrites an existing one with the same name."""
        def old_filter(s: str) -> str:
            return "old"

        def new_filter(s: str) -> str:
            return "new"

        app.add_template_filter(old_filter, name="conflict")
        assert app.jinja_env.filters["conflict"] == old_filter

        app.add_template_filter(new_filter, name="conflict")
        assert app.jinja_env.filters["conflict"] == new_filter
        assert app.jinja_env.filters["conflict"]("anything") == "new"

    def test_add_template_filter_is_callable(self, app: ConcreteAppForTesting):
        """Test that the registered object behaves as a callable in the Jinja environment."""
        def shout(text: str) -> str:
            return f"{text}!"

        app.add_template_filter(shout, name="shout")
        registered_filter = app.jinja_env.filters["shout"]

        assert callable(registered_filter)
        assert registered_filter("hello") == "hello!"

