import pytest
import click
from flask import Flask, current_app
from flask.cli import decorator


class TestDecorator:
    def test_decorator_with_no_app_context(self, runner):
        """Test decorator loads app context if none exists."""
        app = Flask("test_app")

        @click.command()
        @decorator
        def test_cmd(ctx):
            assert current_app is not None
            assert current_app.name == "test_app"
            return "success"

        @click.group()
        def cli():
            pass

        cli.add_command(test_cmd)

        # Use the runner to invoke the command without an existing context
        # Note: In actual CLI usage, app object is usually passed via ctx.obj
        # Here we simulate the invocation logic expected by decorator
        result = runner.invoke(cli, ["test_cmd"], obj=app)
        assert result.exit_code == 0
        assert "success" in result.output

    def test_decorator_with_existing_app_context(self):
        """Test decorator uses existing app context."""
        app = Flask("test_app_existing")

        @click.command()
        @decorator
        def test_cmd(ctx):
            assert current_app is not None
            assert current_app.name == "test_app_existing"
            return "active"

        # Simulate an active context
        with app.app_context():
            with click.Context(test_cmd) as ctx:
                output = decorator.callback(ctx)
                assert output == "active"

    def test_decorator_forwards_args_and_kwargs(self):
        """Test that decorator forwards arguments correctly."""
        app = Flask("test_app_args")

        def target_func(ctx, arg1, arg2, option=None):
            return f"{arg1}-{arg2}-{option}"

        @click.command()
        @click.argument("arg1")
        @click.argument("arg2")
        @click.option("--option")
        @decorator
        def test_cmd(ctx, arg1, arg2, option):
            return target_func(ctx, arg1, arg2, option=option)

        with app.app_context():
            with click.Context(test_cmd) as ctx:
                # We must ensure the context info (like params) is set if we invoke manually
                # but usually decorator wraps the callback. 
                # Here we test the standalone function behavior described.
                res = decorator(ctx, "a", "b", option="c")
                assert res == "a-b-c"

    def test_decorator_without_click_context_raises_error(self):
        """Test that decorator fails gracefully if click context is missing."""
        app = Flask("test_app_error")

        # The function signature is decorator(ctx, /, *args, **kwargs)
        # If passed incorrectly, it might raise TypeError or internal Click errors
        # depending on implementation details of the wrapper.
        # Assuming standard usage:

        @click.command()
        @decorator
        def test_cmd(ctx):
            return "fail"

        # Attempting to call with no context at all (invalid usage)
        with pytest.raises(TypeError):
            decorator(None)

    def test_decorator_with_invalid_app_obj_in_context(self, runner):
        """Test behavior when ctx.obj is not a valid app."""

        @click.command()
        @decorator
        def test_cmd(ctx):
